{'code': "canvas = iface.mapCanvas()
items = [i for i in canvas.scene().items() if type(i).__name__=='QgsMapCanvasAnnotationItem']
out=[]
for it in items:
    info={}
    try:
        ann = it.annotation()
        info['ann_type'] = ann.metaObject().className() if hasattr(ann,'metaObject') else type(ann).__name__
        info['map_pos'] = [ann.mapPosition().x(), ann.mapPosition().y()]
        info['contents'] = getattr(ann,'contents','')
        info['designer'] = getattr(ann,'designerForm','')
        info['visible'] = ann.isVisible()
    except Exception as e:
        info['err'] = repr(e)
    out.append(info)
result = out"}
